    svr=inp[sr[0]][0] if sr else None
    svc=inp[0][sc[0]] if sc else None
    rr=runs(sr,H); cc=runs(sc,W)
    src=None
    for ri,(r0,r1) in enumerate(rr):
        for ci,(c0,c1) in enumerate(cc):
            excl=(svr,svc) if svr is not None else ()
            if svc is not None: excl+= (svc,)
            cells=[(i,j,inp[i][j]) for i in range(r0,r1+1) for j in range(c0,c1+1)
                   if inp[i][j] not in (bg,)+excl]
            if cells: src=(ri,ci,cells,r0,c0)
    ri,ci,cells,r0,c0=src
    h=max(p[0] for p in cells)-r0+1; w=max(p[1] for p in cells)-c0+1
    th=[[bg]*w for _ in range(h)]
    for i,j,v in cells: th[i-r0][j-c0]=v
    O=[row[:] for row in inp]
    for a,b in rr:
        for d,e in cc:
            for i in range(h):
                for j in range(w):
                    if th[i][j]!=bg and 0<=a+i<H and 0<=d+j<W:
                        O[a+i][d+j]=th[i][j]
    return O
